mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("edges=(0,1),(1,2),(1,3),(3,4) values=[1,2,3,4,5]","14"),
        ("edges=(0,1),(1,2),(1,3),(3,4) values=[1,1,1,1,1]","4"),
        ("edges=(0,1),(1,2),(1,3),(3,4) values=[2,2,2,2,2]","8"),
        ("edges=(0,1),(0,2),(0,3),(0,4) values=[1,2,3,4,5]","9"),
        ("edges=(0,1),(1,2),(2,3),(3,4) values=[5,4,3,2,1]","6"),
        ("  \nedges=(0,1),(1,2),(1,3),(3,4) values=[1,2,3,4,5]\n  ","14"),
        ("\nedges=(0,1),(1,2),(2,3),(3,4) values=[5,4,3,2,1]\n","6")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS heavy-light");
}
